 "terms": {
  "nbcd": {
   "en": "need-based community development (NBCD)",
   "zh": "以需求為基礎的社區發展",
   "def": "從社區的問題、缺陷與不足出發，靠外部專家調查分析，由上而下、由外而內解決。居民容易變成受助者（課本 pp. 163–165）。"
  },
  "community": {
   "en": "community",
   "zh": "社區",
   "def": "具備四項基本要素：(1) 個人、團體或組織；(2) 地方；(3) 社會互動；(4) 心理認同或歸屬（p. 141）。"
  },
  "community_work": {
   "en": "community work",
   "zh": "社區工作",
   "def": "社會工作的三大方法之一。比個案工作和團體工作更關心外在環境與社會結構對人的影響（p. 142）。"
  },
  "abcd": {
   "en": "asset-based community development (ABCD)",
   "zh": "以資產為基礎的社區發展",
   "def": "從社區既有的資產、優勢和能力出發（例如具備技能的個人、社區組織、文化團體），由下而上、由內而外；居民是貢獻者（pp. 163–165）。"
  },
  "self_det": {
   "en": "community self-determination",
   "zh": "社區自決",
   "def": "社區工作的原則之一：由社區自己做決定，社區工作者是諮詢者，不是決定者（p. 158）。"
  },
  "participation": {
   "en": "community participation",
   "zh": "社區參與",
   "def": "社區工作的原則之一：居民一起投入社區事務的討論、決定與行動（pp. 155, 158）。"
  },
  "sense": {
   "en": "sense of community",
   "zh": "社區意識",
   "def": "社區成員之間的連結程度，以及他們對環境相互關係的認知（p. 159）。"
  },
  "capacity": {
   "en": "community capacity building",
   "zh": "社區能力建構",
   "def": "幫助社區成員、團體或組織發展技能和能力，以增強社區解決問題、適應挑戰、提供服務及實現目標的能力（p. 170）。"
  },
  "committee": {
   "en": "steering committee",
   "zh": "指導委員會",
   "def": "社區工作實務過程的第一步：由社區中各方代表組成，負責指導整個社區發展的推動與執行（p. 166）。"
  },
  "social_planning": {
   "en": "social planning",
   "zh": "社會計畫",
   "def": "Rothman 模式之一：透過科學理性的方法與技術（蒐集並分析資料）解決具體的社會問題；工作者像專家（pp. 161–162）。"
  },
  "social_action": {
   "en": "social action",
   "zh": "社會行動",
   "def": "Rothman 模式之一：主要起因於受壓迫，目標是改變權力結構、重新分配資源；動員群眾、直接行動、談判協商（pp. 161–163）。"
  },
  "locality": {
   "en": "locality development",
   "zh": "地方發展",
   "def": "Rothman 模式之一：擴大社區參與、共同決策，提升社區能力與自助（過程導向）；工作者是使能者、協調者（pp. 161–162）。"
  },
  "mixed": {
   "en": "mixed model",
   "zh": "混合模式",
   "def": "Rothman (2001) 指出，實務上常常需要同時混合使用不同的模式（課本圖 6.2，pp. 163–164）。"
  },
  "park": {
   "en": "PARK",
   "zh": "保留、增加、移除、避免",
   "def": "資料分析後選擇行動的方法：保留 Preserve 重要特色、增加 Add 關鍵資產、移除 Remove 降低生活品質的因素、避免 Keep out 威脅（p. 167）。"
  },
  "dependency": {
   "en": "cycle of dependency",
   "zh": "依賴循環",
   "def": "以需求為基礎的發展前景：居民是受助者、依賴外部援助，援助一停，社區什麼都沒有留下（課本表 6.2，p. 164；p. 166）。"
  },
  "celebrate": {
   "en": "celebrating results",
   "zh": "慶祝成果與表彰成就",
   "def": "社區工作實務過程的第七步：慶祝和表彰可以提高知名度、認可參與者的貢獻，並鼓勵更多人投入（p. 169）。"
  }
 },
